Select a page from the dropdown to view its contents below.

// 1. Define your dropdown menu options
viewof selectedPage = Inputs.select(
  new Map([
    ["Building Footprints", "building_footprints.html"],
    ["Danané Building Footprints", "../docs/Danané_building_footprints.html"]
  ]), 
  {label: "Choose a page to display:", value: "building_footprints.html"}
)







// 2. Dynamically update the iframe source based on the selection
html`&lt;iframe src="${selectedPage}" width="100%" height="600px" style="border:1px solid #ccc; border-radius: 4px;"&gt;&lt;/iframe&gt;`
